package com.salespunch360.mobile.ui.account.sales
import androidx.compose.foundation.layout.*;import androidx.compose.foundation.lazy.LazyColumn;import androidx.compose.foundation.lazy.items;import androidx.compose.material3.*;import androidx.compose.runtime.Composable;import androidx.compose.ui.Modifier;import androidx.compose.ui.text.font.FontWeight;import androidx.compose.ui.unit.dp;import com.salespunch360.mobile.account.array;import com.salespunch360.mobile.account.str;import kotlinx.serialization.json.JsonObject
@Composable fun SalesDocumentDetail(doc:JsonObject,saving:Boolean,onClose:()->Unit,onPost:(String)->Unit){val status=doc.str("status");AlertDialog(onDismissRequest=onClose,title={Text(doc.str("documentNumber").ifBlank{"Sales document"})},confirmButton={if(status=="DRAFT"&&doc.str("type") in listOf("SALES_INVOICE","CREDIT_NOTE"))Button(enabled=!saving,onClick={onPost(doc.str("id"))}){Text("Post")}},dismissButton={TextButton(onClose){Text("Close")}},text={LazyColumn(verticalArrangement=Arrangement.spacedBy(8.dp)){item{Text("${doc.str("type").replace('_',' ')} · $status",fontWeight=FontWeight.Bold);Text(doc.str("partyName"));Text("Issue ${doc.str("issueDate").take(10)}${doc.str("dueDate").takeIf{it.isNotBlank()}?.let{" · Due ${it.take(10)}"}.orEmpty()}")};items(doc.array("lines")){line->ListItem(headlineContent={Text(line.str("itemName"))},supportingContent={Text("${line.str("quantity")} × ₹${line.str("rate")}")},trailingContent={Text("₹${line.str("lineTotal")}")})};item{HorizontalDivider();Total("Subtotal",doc.str("subtotal"));Total("Discount",doc.str("discountTotal"));Total("CGST",doc.str("cgstTotal"));Total("SGST",doc.str("sgstTotal"));Total("IGST",doc.str("igstTotal"));Total("Tax",doc.str("taxTotal"));Total("Grand total",doc.str("grandTotal"),true);doc["financial"]?.let{Text("Payment: ${it.toString()}")};doc.str("notes").takeIf{it.isNotBlank()}?.let{Text("Notes: $it")}}}})}
@Composable private fun Total(label:String,value:String,strong:Boolean=false){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text(label,fontWeight=if(strong)FontWeight.Bold else null);Text("₹$value",fontWeight=if(strong)FontWeight.Bold else null)}}
